// Assemble a self-contained Sub-Store script from the source fragments under
// internal/build/src/<core>/. Each fragment may define an `entrypoint` and/or
// `postEntrypoint` function. The builder gives both functions a unique name
// derived from the file name and invokes all entrypoints before post entrypoints.

const fs = require("fs");
const path = require("path");
const acorn = require("acorn");
const walk = require("acorn-walk");

const repoRoot = path.join(__dirname, "..", "..");
const srcRoot = path.join(repoRoot, "internal", "build", "src");
const featuresDir = path.join(repoRoot, "features");
const outDir = path.join(repoRoot, "internal");

const targets = [
  { core: "box", out: "buildbox" },
];

const banner = (core) =>
  [
    "// Code generated by script/bundle-build. DO NOT EDIT.",
    `// Edit the sources in internal/build/src/${core}/ and run \`make bundle\`.`,
  ].join("\n");

const listJs = (dir) =>
  fs
    .readdirSync(dir, { withFileTypes: true })
    .flatMap((entry) => {
      const file = path.join(dir, entry.name);
      return entry.isDirectory() ? listJs(file) : entry.name.endsWith(".js") ? [file] : [];
    })
    .sort((a, b) => a.localeCompare(b));

const loadOrder = () =>
  fs
    .readFileSync(path.join(featuresDir, "load-order"), "utf8")
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line && !line.startsWith("#"));

const featureFile = (name) => path.join(featuresDir, name, "load.js");

const sourceBody = (file) => fs.readFileSync(file, "utf8").replace(/^#!.*\n/, "");

// Fragments and features are inlined as plain script bodies (features inside
// an arrow function), so parse them as scripts and allow a top-level return.
const parseSource = (body, file) => {
  try {
    return acorn.parse(body, {
      ecmaVersion: "latest",
      sourceType: "script",
      allowReturnOutsideFunction: true,
      allowAwaitOutsideFunction: true,
    });
  } catch (error) {
    throw new Error(`${path.relative(repoRoot, file)}: ${error.message}`);
  }
};

// `lib.foo` is the public dependency syntax for a build library. Assignment
// sites are included too, which lets a library expose a nested dependency.
const libReferences = (ast) => {
  const names = new Set();
  walk.simple(ast, {
    MemberExpression(node) {
      if (
        !node.computed &&
        node.object.type === "Identifier" &&
        node.object.name === "lib" &&
        node.property.type === "Identifier"
      ) {
        names.add(node.property.name);
      }
    },
  });
  return names;
};

const resolveFeatures = (rootReferences, order) => {
  const needed = new Set();
  const queue = [...rootReferences].filter((name) => name !== "default");
  while (queue.length) {
    const name = queue.shift();
    if (needed.has(name)) continue;
    if (!order.includes(name)) {
      throw new Error(`lib.${name} is not listed in features/load-order`);
    }
    const file = featureFile(name);
    if (!fs.existsSync(file)) {
      throw new Error(`lib.${name} not found at ${file}`);
    }
    needed.add(name);
    for (const dependency of libReferences(parseSource(sourceBody(file), file))) {
      if (dependency !== "default" && dependency !== name) queue.push(dependency);
    }
  }
  return needed;
};

const identifierFor = (file) => {
  const name = path.basename(file).replace(/[^A-Za-z0-9_$]/g, "_");
  return `_${name}`;
};

const entryKinds = {
  entrypoint: "entry",
  post_entrypoint: "post",
  postEntrypoint: "post",
};

// Only top-level bindings count as entrypoints, so commented-out code and
// nested helpers that happen to share the name are ignored.
const topLevelEntries = (ast, file) => {
  const ids = [];
  for (const node of ast.body) {
    if (node.type === "FunctionDeclaration") ids.push(node.id);
    else if (node.type === "VariableDeclaration") {
      for (const declarator of node.declarations) {
        if (declarator.id.type === "Identifier") ids.push(declarator.id);
      }
    }
  }

  const entries = { entry: undefined, post: undefined };
  for (const id of ids) {
    const kind = entryKinds[id.name];
    if (!kind) continue;
    if (entries[kind]) {
      throw new Error(
        `${path.relative(repoRoot, file)}: duplicate ${kind} entrypoint \`${id.name}\``,
      );
    }
    entries[kind] = id;
  }
  return entries;
};

// Rename only the declaring identifier, splicing from the end so earlier
// offsets stay valid.
const renameIdentifiers = (body, renames) =>
  renames
    .sort((a, b) => b.id.start - a.id.start)
    .reduce(
      (text, { id, name }) => text.slice(0, id.start) + name + text.slice(id.end),
      body,
    );

const preparePart = (file, coreDir) => {
  const raw = sourceBody(file);
  const ast = parseSource(raw, file);
  const identifier = identifierFor(file);
  const entryName = `${identifier}_entrypoint`;
  const postName = `${identifier}_post_entrypoint`;
  const entries = topLevelEntries(ast, file);

  const renames = [];
  if (entries.entry) renames.push({ id: entries.entry, name: entryName });
  if (entries.post) renames.push({ id: entries.post, name: postName });
  const body = renameIdentifiers(raw, renames);

  return {
    file,
    relative: path.relative(coreDir, file),
    body: body.trimEnd(),
    hasEntrypoint: !!entries.entry,
    hasPostEntrypoint: !!entries.post,
    entryName,
    postName,
    libs: libReferences(ast),
  };
};

const invoke = (name, value) =>
  `${name}({ ...(${value} || {}), lib: __lib, constant: __constant, context: __context })`;

const assemble = (core) => {
  const dir = path.join(srcRoot, core);
  if (!fs.existsSync(dir)) throw new Error(`source directory not found: ${dir}`);
  const files = listJs(dir);
  if (!files.length) throw new Error(`no source files found under ${dir}`);

  const parts = files.map((file) => preparePart(file, dir));
  const order = loadOrder();
  const rootReferences = new Set();
  for (const part of parts) {
    for (const name of part.libs) rootReferences.add(name);
  }
  const needed = resolveFeatures(rootReferences, order);
  const featureBlocks = order
    .filter((name) => needed.has(name))
    .map((name) => {
      const body = sourceBody(featureFile(name)).trimEnd();
      return `// lib: ${name}\n(() => {\n${body}\n})();`;
    });

  // entry.js is the global main function and seeds the chain. Other
  // entrypoints follow file order. Post entrypoints are a stack: a post
  // function is pushed as its fragment is reached and the stack is drained
  // after all entrypoints, so entry.js post processing runs last.
  const entryParts = parts.filter((part) => part.hasEntrypoint);
  const main = entryParts.find((part) => part.relative === "entry.js");
  if (!main) throw new Error(`${dir}: entry.js must define entrypoint`);
  const orderedEntries = [main, ...entryParts.filter((part) => part !== main)];
  const postCandidates = [
    main,
    ...parts.filter((part) => part !== main && part.hasPostEntrypoint),
  ].filter((part) => part.hasPostEntrypoint);
  const orderedPosts = postCandidates.reverse();
  const calls = [
    ...orderedEntries.map((part) => part.entryName),
    ...orderedPosts.map((part) => part.postName),
  ];
  if (!calls.length) throw new Error(`${dir}: no entrypoint functions found`);

  const chain = [
    `await ${invoke(calls[0], "{}")}`,
    ...calls.slice(1).map((name) => `  .then((value) => ${invoke(name, "value")})`),
    ";",
  ].join("\n");
  const body = [
    banner(core),
    "const __lib = {};",
    "const lib = __lib;",
    "const constant = {};",
    "const __constant = constant;",
    "const __context = typeof context === \"undefined\" ? {} : context;",
    ...featureBlocks,
    ...parts.map((part) => part.body).filter(Boolean),
    chain,
  ].join("\n\n") + "\n";

  return {
    body,
    files: files.length,
    features: featureBlocks.length,
    entrypoints: orderedEntries.length,
    postEntrypoints: orderedPosts.length,
  };
};

const main = async () => {
  for (const { core, out } of targets) {
    const result = assemble(core);
    fs.writeFileSync(path.join(outDir, `${out}.js`), result.body);
    console.log(
      `generated internal/${out}.js from ${result.files} parts, ${result.features} libs, ${result.entrypoints} entrypoints, ${result.postEntrypoints} post-entrypoints`,
    );
  }
};

main().catch((error) => {
  console.error(error.message ?? error);
  process.exit(1);
});
